static uint32_t read_flow_rate(void)
{
    uint32_t pulses = 0U;
    taskENTER_CRITICAL();

    pulse_count = 0U;
    taskEXIT_CRITICAL();
    return pulses / PULSES_PER_UNIT;
}

int main(void)
{
    uint32_t next_report;

    HAL_Init();
    gpio_init();

    next_report = HAL_GetTick() + WINDOW_MS;

    for (;;) {
