            uint32_t rate = read_flow_rate();

            HAL_GPIO_WritePin(LED_PORT, LED_PIN,
                              (rate > FLOW_LIMIT) ? GPIO_PIN_SET : GPIO_PIN_RESET);
            next_report += WINDOW_MS;
        }
    }
